#include <stdio.h>

int main() {
    int a, b, c, temp;
    printf("请输入三个整数 a b c: ");
    scanf("%d %d %d", &a, &b, &c);

    temp = b;
    b = a;
    a = c;
    c = temp;

    // 题目要求: a原值->b, b原值->c, c原值->a
    // 修正逻辑: 
    // t = b (保存b原值)
    // b = a (b变a原值)
    // a = c (a变c原值) -> 错误，a变c原值，但c应变b原值
    // 正确逻辑: 
    // t = c;
    // c = b;
    // b = a;
    // a = t;

    printf("交换后: a=%d, b=%d, c=%d\n", a, b, c);
    return 0;
}

questions.analysis:
这是一个循环移位问题。需要借助临时变量temp。逻辑：temp=c; c=b; b=a; a=temp; 即可实现 a<-c, c<-b, b<-a (即 a->b, b->c, c->a 的逆过程? 题目说 a原值给b... 意味着 b_new = a_old, c_new = b_old, a_new = c_old)。
代码实现：
int t = c;
c = b;
b = a;
a = t;

