#include <stdio.h>

int main() {
    int year, month, days;
    printf("Enter year and month: ");
    scanf("%d %d", &year, &month);

    switch (month) {
        case 1: case 3: case 5: case 7: case 8: case 10: case 12:
            days = 31;
            break;
        case 4: case 6: case 9: case 11:
            days = 30;
            break;
        case 2:
            if ((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)) {
                days = 29;
            } else {
                days = 28;
            }
            break;
        default:
            printf("Invalid month\n");
            return 1;
    }

    printf("Days: %d\n", days);
    return 0;
}

#include <stdio.h>

int main() {
    float p, w, s, f, d;
    int c;
    printf("Enter price, weight, distance: ");
    scanf("%f %f %f", &p, &w, &s);

    if (s >= 3000) c = 12;
    else c = s / 250;

    switch (c) {
        case 0: d = 0; break;
        case 1: d = 0.02; break;
        case 2: case 3: d = 0.05; break;
        case 4: case 5: case 6: case 7: d = 0.08; break;
        case 8: case 9: case 10: case 11: d = 0.10; break;
        default: d = 0.15; break;
    }

    f = p * w * s * (1 - d);
    printf("Total freight: %.2f\n", f);
    return 0;
}

