#include <stdio.h>

int main() {
    int n;
    int c3 = 0, c5 = 0, c7 = 0;
    printf("Enter an integer: ");
    scanf("%d", &n);

    if (n % 3 == 0) c3 = 1;
    if (n % 5 == 0) c5 = 1;
    if (n % 7 == 0) c7 = 1;

    int sum = c3 + c5 + c7;

    if (sum == 3) {
        printf("Can be divided by 3, 5, 7\n");
    } else if (sum == 2) {
        printf("Can be divided by two numbers: ");
        if (c3 && c5) printf("3 and 5\n");
        if (c3 && c7) printf("3 and 7\n");
        if (c5 && c7) printf("5 and 7\n");
    } else if (sum == 1) {
        printf("Can be divided by one number: ");
        if (c3) printf("3\n");
