#include <stdio.h>

int main() {
    int a[10], odd[10], even[10];
    int i, j, k, t, o_cnt = 0, e_cnt = 0;

    printf("Input 10 numbers:\n");
    for(i = 0; i < 10; i++) {
        scanf("%d", &a[i]);
        if(a[i] % 2 != 0) odd[o_cnt++] = a[i];
        else even[e_cnt++] = a[i];
    }

    // Sort odd numbers
    for(i = 0; i < o_cnt - 1; i++)
        for(j = 0; j < o_cnt - 1 - i; j++)
            if(odd[j] > odd[j+1]) { t = odd[j]; odd[j] = odd[j+1]; odd[j+1] = t; }

    // Sort even numbers
    for(i = 0; i < e_cnt - 1; i++)
        for(j = 0; j < e_cnt - 1 - i; j++)
            if(even[j] > even[j+1]) { t = even[j]; even[j] = even[j+1]; even[j+1] = t; }

    // Output
    for(i = 0; i < o_cnt; i++) printf("%d ", odd[i]);
    for(i = 0; i < e_cnt; i++) printf("%d ", even[i]);
    printf("\n");

    return 0;
}
