#include <stdio.h>

int main() {
    int a[5][5], i, j;
    int sum = 0;
    long long product = 1;

    printf("Input 5x5 matrix:\n");
    for(i = 0; i < 5; i++)
        for(j = 0; j < 5; j++)
            scanf("%d", &a[i][j]);

    for(i = 0; i < 5; i++) {
        sum += a[i][i]; // 主对角线
        if(i != 2) sum += a[i][4-i]; // 副对角线，避免中心元素重复加（如果题目意图是不重复加）
        // 通常题目意图是简单累加，若中心元素算两次则去掉if
    }
    // 简单累加版本（中心元素加两次）：
    sum = 0;
    for(i=0; i<5; i++) sum += a[i][i] + a[i][4-i];
    if(5%2!=0) sum -= a[2][2]; // 减去重复加的中心

    for(i = 0; i < 5; i++) {
        if(i % 2 == 0) {
            // 主对角线 (i, i)
            product *= a[i][i];
            // 副对角线 (i, 4-i), 4-i 也是偶数
            if(i != 2) product *= a[i][4-i]; // 避免中心乘两次
        }
    }

    printf("Sum: %d\n", sum);
    printf("Product: %lld\n", product);
    return 0;
}
