#include <stdio.h>
#define M 3
#define N 3

int main() {
    int a[M][N], i, j, k, max_j, flag, found = 0;

    printf("Input %dx%d matrix:\n", M, N);
    for(i = 0; i < M; i++)
        for(j = 0; j < N; j++)
            scanf("%d", &a[i][j]);

    for(i = 0; i < M; i++) {
        // 找第i行最大值
        max_j = 0;
        for(j = 1; j < N; j++)
            if(a[i][j] > a[i][max_j]) max_j = j;

        // 检查是否为该列最小值
        flag = 1;
        for(k = 0; k < M; k++)
            if(a[k][max_j] < a[i][max_j]) {
                flag = 0;
                break;
            }

        if(flag) {
            printf("Saddle point at (%d, %d) = %d\n", i, max_j, a[i][max_j]);
            found = 1;
        }
    }

    if(!found) printf("No saddle point.\n");
    return 0;
}
