char *substr(char *s, int startloc, int len) {
    char *sub;
    int s_len = strlen(s);
    int i;

    if (startloc >= s_len) {
        sub = (char *)malloc(1);
        sub[0] = '\0';
        return sub;
    }

    // 调整长度，防止越界
    if (startloc + len > s_len) {
        len = s_len - startloc;
    }

    sub = (char *)malloc((len + 1) * sizeof(char));
    if (sub == NULL) return NULL;

    for (i = 0; i < len; i++) {
        sub[i] = s[startloc + i];
    }
    sub[len] = '\0';
    return sub;
}

int main() {
