void strlshif(char *s, int n) {
    int len = strlen(s);
    if (len == 0 || n <= 0) return;
    n %= len;

    char *temp = (char *)malloc(n * sizeof(char));
    // 保存前n个字符
    strncpy(temp, s, n);

    // 移动剩余字符
    int i;
    for (i = 0; i < len - n; i++) {
        s[i] = s[i + n];
    }

    // 将保存的字符放到末尾
    for (int j = 0; j < n; j++) {
        s[len - n + j] = temp[j];
    }
    s[len] = '\0';
    free(temp);
}

