// 假设a >= b
void sub_large(char *a, char *b, char *res) {
    int len_a = strlen(a);
    int len_b = strlen(b);
    int i, j, k;
    int borrow = 0;

    // 反转存储或直接从尾部处理
    // 这里从尾部向前处理
    res[len_a] = '\0';
    k = len_a - 1;
    i = len_a - 1;
    j = len_b - 1;

    while (i >= 0) {
        int val_a = a[i] - '0';
        int val_b = (j >= 0) ? (b[j] - '0') : 0;

        int diff = val_a - val_b - borrow;
        if (diff < 0) {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        res[k--] = diff + '0';
        i--;
        j--;
    }

    // 去除前导0
    char *p = res;
    while (*p == '0' && *(p+1) != '\0') p++;
    if (p != res) strcpy(res, p);
}

int main() {
    char n1[1000], n2[1000], res[1000];
    printf("Input two large numbers:\n");
    scanf("%s%s", n1, n2);

    // 简单比较大小逻辑省略，假设输入n1 >= n2
    sub_large(n1, n2, res);
    printf("Result: %s\n", res);
    return 0;
}

