#include <stdio.h>
#include <stdlib.h>

void move(int *arr, int n, int m) {
    if (n <= 0 || m <= 0) return;
    m %= n;
    int *temp = (int *)malloc(m * sizeof(int));

    // 保存最后m个数
    for (int i = 0; i < m; i++) {
        temp[i] = arr[n - m + i];
    }

    // 后移前面的n-m个数
    for (int i = n - 1; i >= m; i--) {
        arr[i] = arr[i - m];
    }

    // 将保存的数放回前面
    for (int i = 0; i < m; i++) {
        arr[i] = temp[i];
    }

    free(temp);
}

int main() {
    int n, m, i;
    printf("Enter n: ");
    scanf("%d", &n);
    int *arr = (int *)malloc(n * sizeof(int));
    printf("Enter numbers: ");
    for (i = 0; i < n; i++) scanf("%d", &arr[i]);

    printf("Enter m: ");
    scanf("%d", &m);

    move(arr, n, m);

    printf("Result: ");
    for (i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");

    free(arr);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

void sort(int **p, int n) {
    int i, j;
    int *temp;
    for (i = 0; i < n - 1; i++) {
        for (j = i + 1; j < n; j++) {
            if (**(p + i) > **(p + j)) {
                temp = *(p + i);
                *(p + i) = *(p + j);
                *(p + j) = temp;
            }
        }
    }
}

int main() {
    int n, i;
    printf("Enter n: ");
    scanf("%d", &n);

    int *arr = (int *)malloc(n * sizeof(int));
    int **p = (int **)malloc(n * sizeof(int *));

    printf("Enter numbers: ");
    for (i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
        p[i] = &arr[i];
    }

    sort(p, n);

    printf("Sorted: ");
    for (i = 0; i < n; i++) {
        printf("%d ", *p[i]);
    }
    printf("\n");

    free(arr);
    free(p);
    return 0;
}

