#include <stdio.h>
#include <stdlib.h>

void copyFile(FILE *src, FILE *dest) {
    char ch;
    while ((ch = fgetc(src)) != EOF) {
        fputc(ch, dest);
    }
}

int main(int argc, char *argv[]) {
    FILE *fp1, *fp2, *fp3;
    char ch;

    if (argc != 4) {
        printf("Usage: %s <file1> <file2> <mergefile>\n", argv[0]);
        exit(0);
    }

    if ((fp1 = fopen(argv[1], "r")) == NULL) { printf("Can't open %s\n", argv[1]); exit(0); }
    if ((fp2 = fopen(argv[2], "r")) == NULL) { printf("Can't open %s\n", argv[2]); fclose(fp1); exit(0); }
    if ((fp3 = fopen(argv[3], "w+")) == NULL) { printf("Can't open %s\n", argv[3]); fclose(fp1); fclose(fp2); exit(0); }

    copyFile(fp1, fp3);
    copyFile(fp2, fp3);

    printf("Merged Content:\n");
    rewind(fp3);
    while ((ch = fgetc(fp3)) != EOF) {
        putchar(ch);
    }

    fclose(fp1);
    fclose(fp2);
    fclose(fp3);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    FILE *fp;
    char buffer[1024];
    int currentLine = 1;
    int m = 1, n = -1; // n=-1 表示显示到末尾

    if (argc < 2) {
        printf("Usage: %s filename [m n]\n", argv[0]);
        return 1;
    }

    if (argc >= 3) m = atoi(argv[2]);
    if (argc >= 4) n = atoi(argv[3]);

    if ((fp = fopen(argv[1], "r")) == NULL) {
        printf("Can't open file %s\n", argv[1]);
        return 1;
    }

    while (fgets(buffer, 1024, fp) != NULL) {
        if (currentLine >= m && (n == -1 || currentLine <= n)) {
            printf("%s", buffer);
        }
        if (n != -1 && currentLine > n) break;
        currentLine++;
    }

    fclose(fp);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char no[11];
    char name[21];
    int score;
    int time;
    int rank;
} Student;

int compare(const void *a, const void *b) {
    Student *s1 = (Student *)a;
    Student *s2 = (Student *)b;
    if (s2->score != s1->score) return s2->score - s1->score; // 分数降序
    return s1->time - s2->time; // 时间升序
}

int main() {
    FILE *fp;
    Student stus[100];
    int count = 0, i;

    if ((fp = fopen("score_tab.txt", "r")) == NULL) {
        printf("File not found.\n");
        return 1;
    }

    while (fscanf(fp, "%s %s %d %d", stus[count].no, stus[count].name, &stus[count].score, &stus[count].time) != EOF) {
        count++;
    }
    fclose(fp);

    qsort(stus, count, sizeof(Student), compare);

    printf("Rank\tNo\t\tName\t\tScore\tTime\n");
    for (i = 0; i < count; i++) {
        if (i > 0 && stus[i].score == stus[i-1].score && stus[i].time == stus[i-1].time) {
            stus[i].rank = stus[i-1].rank;
        } else {
            stus[i].rank = i + 1;
        }
        printf("%d\t%s\t%s\t%d\t%d\n", stus[i].rank, stus[i].no, stus[i].name, stus[i].score, stus[i].time);
    }
    return 0;
}

